// Validate input: requires page data + keyword data from data collection step
const input = $input.first().json;
const body = input.body || input;

const config = {
  domain: body.domain || 'kahunaworkforce.com',
  page_url: body.page_url || '',
  page_title: body.page_title || '',
  current_copy: body.current_copy || '',
  target_keywords: body.target_keywords || [],
  keyword_intents: body.keyword_intents || {},
  competitor_urls: body.competitor_urls || [],
  semrush_api_key: body.semrush_api_key || '',
  anthropic_api_key: body.anthropic_api_key || '',
  tone: body.tone || 'professional',
  word_count_target: body.word_count_target || null
};

if (!config.page_url) {
  return [{ json: { error: true, message: 'page_url is required.' } }];
}
if (!config.target_keywords.length) {
  return [{ json: { error: true, message: 'target_keywords array is required (at least 1 keyword).' } }];
}
if (!config.anthropic_api_key) {
  return [{ json: { error: true, message: 'anthropic_api_key is required for Claude copy rewriting.' } }];
}

return [{ json: config }];

// Parse Claude's rewritten copy and SEMrush related keywords
const config = $('Validate Input').first().json;
const claudeRaw = $('Claude: Rewrite Copy').first().json;
const relatedRaw = $('SEMrush: Related Keywords').first().json;

// Parse Claude response
let optimizedCopy = {};
try {
  const content = claudeRaw.content?.[0]?.text || claudeRaw.content || '';
  optimizedCopy = JSON.parse(content);
} catch (e) {
  optimizedCopy = {
    error: 'Failed to parse Claude response',
    raw_response: claudeRaw.content?.[0]?.text || 'No response',
    details: e.message
  };
}

// Parse related keywords for additional optimization suggestions
let relatedKeywords = [];
try {
  if (typeof relatedRaw === 'string' || relatedRaw.data) {
    const csvText = typeof relatedRaw === 'string' ? relatedRaw : relatedRaw.data;
    const lines = csvText.split('\n').filter(l => l.trim());
    if (lines.length > 1) {
      relatedKeywords = lines.slice(1).map(line => {
        const vals = line.split(';');
        return {
          keyword: vals[0],
          volume: parseInt(vals[1] || 0),
          difficulty: parseInt(vals[2] || 0),
          intent: vals[3] || 'unknown'
        };
      });
    }
  }
} catch (e) {
  // Related keywords are supplementary, don't fail
}

return [{
  json: {
    pipeline_step: 'content_optimization',
    domain: config.domain,
    page_url: config.page_url,
    generated_at: new Date().toISOString(),
    optimized_content: optimizedCopy,
    related_keywords_to_consider: relatedKeywords.slice(0, 10),
    validation_status: 'pending_semrush_check',
    next_steps: [
      'Run SEMrush On-Page SEO Checker to validate optimization',
      'Review optimized copy for brand voice consistency',
      'Schedule for staged rollout (2 pages/week)'
    ]
  }
}];
